import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useLocation, useParams, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { tours } from '../data/mockData';
import { getBusinessForStop, getLoyaltyProgramForBusiness, getOfferForBusiness } from '../data/localMarketplace';
import { getNarrationStatus, getNarrationTrack, getNarrationVoice } from '../data/audioManifest';
import SafeIcon from '../common/SafeIcon';
import { clearLocalEvents, getStorageKey, readLocalEvents, recordLocalEvent, safeRead, safeWrite } from '../utils/localEvents';
import { getDisplayTourTitle, getPreviewMode, withPreviewMode } from '../utils/previewMode';

const tabs = ['On approach', 'At the stop', 'Safety', 'Offers'];

function StylizedMap({ currentStop, currentStopIndex, tour, reviewerMode, displayTitle }) {
  const pinPositions = [
    ['18%', '72%'], ['32%', '48%'], ['48%', '58%'], ['58%', '38%'], ['72%', '46%'], ['82%', '28%'], ['62%', '76%']
  ];

  return (
    <div className="flex-1 relative overflow-hidden bg-[#dfe8df]">
      <div className="absolute inset-0 opacity-70">
        <div className="absolute left-[-20%] top-[10%] h-28 w-[140%] rotate-[-8deg] rounded-full bg-white/50" />
        <div className="absolute left-[8%] top-[35%] h-20 w-[100%] rotate-[18deg] rounded-full bg-white/45" />
        <div className="absolute right-[-20%] top-[8%] h-[120%] w-40 rounded-full bg-teal-900/10" />
        <div className="absolute left-[12%] bottom-[12%] h-24 w-36 rounded-[40%] bg-orange-900/10" />
        <svg className="absolute inset-0 h-full w-full" viewBox="0 0 100 100" preserveAspectRatio="none">
          <path d="M 18 72 C 28 50, 42 62, 48 58 S 62 35, 72 46 S 88 40, 82 28" fill="none" stroke="#c2410c" strokeWidth="2.5" strokeLinecap="round" strokeDasharray="3 3" />
        </svg>
      </div>

      <div className="absolute left-4 top-24 z-10 rounded-2xl bg-white/90 px-3 py-2 text-[10px] font-bold uppercase tracking-widest text-slate-600 shadow-sm backdrop-blur">
        Route sketch · use Open in Maps for real navigation
      </div>

      <div className="absolute left-4 top-40 z-10 flex flex-wrap gap-2 max-w-[70%]">
        {tour.clusters?.slice(0, 3).map(cluster => (
          <span key={cluster} className="rounded-full bg-white/90 px-3 py-1 text-[10px] font-bold text-slate-700 shadow-sm">
            {cluster}
          </span>
        ))}
      </div>

      <div className="absolute right-4 top-28 z-10 flex flex-col gap-2" aria-label="Map controls pending real map integration">
        <div className="w-10 h-10 bg-white/70 rounded-full shadow-md flex items-center justify-center text-slate-400" title="Real map pending">
          <SafeIcon name="Compass" className="w-5 h-5" />
        </div>
        <div className="w-10 h-10 bg-white/70 rounded-full shadow-md flex items-center justify-center text-slate-400" title="Map layers pending">
          <SafeIcon name="Layers" className="w-5 h-5" />
        </div>
      </div>

      {pinPositions.slice(0, tour.stops?.length || pinPositions.length).map(([left, top], index) => {
        const active = index === currentStopIndex;
        return (
          <div key={`${left}-${top}`} className="absolute z-10" style={{ left, top }}>
            <div className={`${active ? 'h-9 w-9 bg-orange-700' : 'h-7 w-7 bg-slate-700'} border-2 border-white rounded-full shadow-lg flex items-center justify-center`}>
              <span className="text-white font-bold text-xs">{index + 1}</span>
            </div>
          </div>
        );
      })}

      <div className="absolute bottom-16 left-5 right-5 rounded-2xl bg-white/90 p-3 shadow-lg backdrop-blur">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="text-[10px] font-bold uppercase tracking-widest text-orange-700">{reviewerMode ? 'Loaded tour pack' : 'Current tour'}</p>
            <p className="text-sm font-bold text-slate-900">{reviewerMode ? tour.packId : displayTitle}</p>
          </div>
          <span className="rounded-full bg-emerald-100 px-2 py-1 text-[10px] font-bold text-emerald-800">Offline ready</span>
        </div>
      </div>
    </div>
  );
}

export default function Player() {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const tour = tours.find(t => t.id === id) || tours[0];
  const previewMode = getPreviewMode(location.search);
  const reviewerMode = previewMode === 'reviewer';
  const displayTitle = getDisplayTourTitle(tour, previewMode);
  const [currentStopIndex, setCurrentStopIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showStopDetail, setShowStopDetail] = useState(false);
  const [activeTab, setActiveTab] = useState(tabs[1]);
  const [visitedStops, setVisitedStops] = useState([]);
  const [savedStops, setSavedStops] = useState([]);
  const [activatedOffers, setActivatedOffers] = useState([]);
  const [loyaltyStamps, setLoyaltyStamps] = useState({});
  const [recentEvents, setRecentEvents] = useState([]);
  const [fieldNotes, setFieldNotes] = useState({});
  const [shareStatus, setShareStatus] = useState('');
  const [audioStatus, setAudioStatus] = useState('');
  const impressionKeys = useRef(new Set());
  const audioRef = useRef(null);

  const firstOfferStopIndex = tour.stops?.findIndex(stop => getBusinessForStop(tour.id, stop.id)) ?? -1;
  const firstOfferStop = firstOfferStopIndex >= 0 ? tour.stops[firstOfferStopIndex] : null;
  const currentStop = tour.stops?.[currentStopIndex] || tour.stops?.[0];
  const business = currentStop ? getBusinessForStop(tour.id, currentStop.id) : null;
  const offer = business ? getOfferForBusiness(business.id) : null;
  const loyaltyProgram = business ? getLoyaltyProgramForBusiness(business.id) : null;
  const narrationLanguage = tour.city?.includes('JP') ? 'japaneseFemale' : 'english';
  const narrationVoice = getNarrationVoice(narrationLanguage);
  const narrationTrack = getNarrationTrack(tour.id, currentStop?.id, narrationLanguage);
  const narrationStatus = getNarrationStatus(tour.id, currentStop?.id, narrationLanguage);
  const generatedAudioScript = currentStop?.narrationScripts?.[narrationLanguage] || '';
  const narrationLanguageLabel = narrationVoice.label || narrationLanguage;
  const narrationLabel = reviewerMode
    ? narrationTrack?.audioUrl ? `Generated audio ready · ${narrationVoice.defaultVoice}` : `Script ready · TTS pending · ${narrationVoice.defaultVoice}`
    : narrationTrack?.audioUrl ? 'Audio ready' : 'Narration script ready';
  const currentFieldNote = currentStop ? fieldNotes[currentStop.id] || '' : '';
  const offerActive = offer ? activatedOffers.includes(offer.id) : false;
  const stampCount = loyaltyProgram ? (loyaltyStamps[loyaltyProgram.id] || 0) : 0;
  const offerTitle = reviewerMode ? offer?.title : offer?.consumerTitle || offer?.title;
  const offerDescription = reviewerMode ? offer?.description : offer?.consumerDescription || offer?.description;
  const offerRelevanceLabel = reviewerMode ? offer?.relevanceLabel : offer?.consumerRelevanceLabel || offer?.relevanceLabel;
  const exactMapsAllowed = currentStop?.mapPrecision !== 'area';

  const getTourEvents = () => readLocalEvents().filter(event => event.payload?.tourId === tour.id);

  useEffect(() => {
    const progressKey = getStorageKey('progress', tour.id);
    const offerKey = getStorageKey('offers', tour.id);
    const savedStopsKey = getStorageKey('saved-stops', tour.id);
    const loyaltyKey = getStorageKey('loyalty', tour.id);
    const fieldNoteKey = getStorageKey('field-note', tour.id);
    const fieldNotesKey = getStorageKey('field-notes', tour.id);
    const currentStopKey = getStorageKey('current-stop-index', tour.id);
    const storedVisitedStops = safeRead(progressKey, []);
    const storedFieldNotes = safeRead(fieldNotesKey, {});
    const legacyTourNote = localStorage.getItem(fieldNoteKey);
    const firstStopId = tour.stops?.[0]?.id;

    setVisitedStops(storedVisitedStops);
    setActivatedOffers(safeRead(offerKey, []));
    setSavedStops(safeRead(savedStopsKey, []));
    setLoyaltyStamps(safeRead(loyaltyKey, {}));
    setRecentEvents(getTourEvents().slice(0, 5));
    setFieldNotes(Object.keys(storedFieldNotes).length || !legacyTourNote || !firstStopId ? storedFieldNotes : { [firstStopId]: legacyTourNote });

    const savedIndex = Number(localStorage.getItem(currentStopKey));
    if (Number.isInteger(savedIndex) && savedIndex >= 0 && savedIndex < (tour.stops?.length || 0)) {
      setCurrentStopIndex(savedIndex);
      return;
    }

    const firstUnvisitedIndex = tour.stops?.findIndex(stop => !storedVisitedStops.includes(stop.id)) ?? -1;
    setCurrentStopIndex(firstUnvisitedIndex >= 0 ? firstUnvisitedIndex : 0);
  }, [tour.id]);

  useEffect(() => {
    if (!tour.stops?.length) return;
    localStorage.setItem(getStorageKey('current-stop-index', tour.id), String(currentStopIndex));
  }, [currentStopIndex, tour.id, tour.stops?.length]);

  useEffect(() => {
    if (business && offer) {
      const key = `${tour.id}:${currentStop.id}:${offer.id}`;
      if (!impressionKeys.current.has(key)) {
        impressionKeys.current.add(key);
        recordLocalEvent('offer_impression', { tourId: tour.id, stopId: currentStop.id, businessId: business.id, offerId: offer.id });
      }
    }
  }, [business, currentStop.id, offer, tour.id]);

  const saveVisitedStops = (nextStops) => {
    setVisitedStops(nextStops);
    safeWrite(getStorageKey('progress', tour.id), nextStops);
  };

  const saveActivatedOffers = (nextOffers) => {
    setActivatedOffers(nextOffers);
    safeWrite(getStorageKey('offers', tour.id), nextOffers);
  };

  const saveSavedStops = (nextStops) => {
    setSavedStops(nextStops);
    safeWrite(getStorageKey('saved-stops', tour.id), nextStops);
  };

  const saveLoyaltyStamps = (nextStamps) => {
    setLoyaltyStamps(nextStamps);
    safeWrite(getStorageKey('loyalty', tour.id), nextStamps);
  };

  const logEvent = (type, payload) => {
    const event = recordLocalEvent(type, payload);
    setRecentEvents([event, ...getTourEvents().filter(item => item.id !== event.id)].slice(0, 5));
    return event;
  };

  const markVisited = () => {
    const nextVisitedStops = visitedStops.includes(currentStop.id) ? visitedStops : [...visitedStops, currentStop.id];
    saveVisitedStops(nextVisitedStops);
    logEvent('stop_completed', { tourId: tour.id, stopId: currentStop.id, stopNumber: currentStop.number });
    setCurrentStopIndex(Math.min(tour.stops.length - 1, currentStopIndex + 1));
  };

  const saveCurrentStop = () => {
    const nextSavedStops = savedStops.includes(currentStop.id) ? savedStops : [...savedStops, currentStop.id];
    saveSavedStops(nextSavedStops);
    logEvent('stop_saved', { tourId: tour.id, stopId: currentStop.id, stopNumber: currentStop.number });
  };

  const activateOffer = () => {
    if (!offer || !business) return;
    const nextOffers = activatedOffers.includes(offer.id) ? activatedOffers : [...activatedOffers, offer.id];
    saveActivatedOffers(nextOffers);
    logEvent('offer_activate', { tourId: tour.id, stopId: currentStop.id, businessId: business.id, offerId: offer.id });
  };

  const addLoyaltyStamp = () => {
    if (!loyaltyProgram || !business) return;
    const nextCount = Math.min(loyaltyProgram.requiredStamps, stampCount + 1);
    const nextStamps = { ...loyaltyStamps, [loyaltyProgram.id]: nextCount };
    saveLoyaltyStamps(nextStamps);
    logEvent('loyalty_stamp_granted', { tourId: tour.id, stopId: currentStop.id, businessId: business.id, loyaltyProgramId: loyaltyProgram.id, stamps: nextCount, verificationMode: loyaltyProgram.verificationMode });
  };

  const addFieldSignal = (signal) => {
    logEvent('field_signal', {
      tourId: tour.id,
      stopId: currentStop.id,
      businessId: business?.id || null,
      signal
    });
  };

  const saveFieldNote = (note) => {
    const nextNotes = { ...fieldNotes, [currentStop.id]: note };
    setFieldNotes(nextNotes);
    safeWrite(getStorageKey('field-notes', tour.id), nextNotes);
  };

  const toggleNarration = async () => {
    if (narrationTrack?.audioUrl && audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
        setIsPlaying(false);
        setAudioStatus('Paused');
      } else {
        try {
          await audioRef.current.play();
          setIsPlaying(true);
          setAudioStatus('Playing audio');
          logEvent('narration_played', { tourId: tour.id, stopId: currentStop.id, voice: narrationTrack.voice, language: narrationLanguage });
        } catch {
          setAudioStatus('Use native audio controls below');
        }
      }
      return;
    }

    setIsPlaying(!isPlaying);
  };

  const shareFieldTestLink = async () => {
    const url = window.location.href.split('?')[0];
    const sharePayload = {
      title: displayTitle,
      text: `${reviewerMode ? 'Tour Engine field test' : 'Tour Engine'}: ${displayTitle}`,
      url
    };

    try {
      if (navigator.share) {
        await navigator.share(sharePayload);
        setShareStatus('Shared');
      } else if (navigator.clipboard) {
        await navigator.clipboard.writeText(url);
        setShareStatus('Copied link');
      } else {
        setShareStatus('Copy URL from address bar');
      }
    } catch {
      setShareStatus('Share canceled');
    }

    window.setTimeout(() => setShareStatus(''), 2500);
  };

  const openCurrentStopInMaps = () => {
    const coordinates = exactMapsAllowed ? currentStop.coordinates?.replace(/\s+/g, '') : '';
    const query = coordinates || `${currentStop.location}, ${tour.city}`;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
    logEvent('maps_opened', {
      tourId: tour.id,
      stopId: currentStop.id,
      coordinates: coordinates || null,
      exactCoordinatesSuppressed: !exactMapsAllowed
    });
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  const jumpToOfferStop = () => {
    if (!firstOfferStop || firstOfferStopIndex < 0) return;
    setCurrentStopIndex(firstOfferStopIndex);
    logEvent('reviewer_offer_stop_jump', { tourId: tour.id, stopId: firstOfferStop.id, routePosition: firstOfferStopIndex + 1, sourceStopNumber: firstOfferStop.number });
  };

  const resetDemoState = () => {
    localStorage.removeItem(getStorageKey('progress', tour.id));
    localStorage.removeItem(getStorageKey('offers', tour.id));
    localStorage.removeItem(getStorageKey('loyalty', tour.id));
    localStorage.removeItem(getStorageKey('saved-stops', tour.id));
    localStorage.removeItem(getStorageKey('field-note', tour.id));
    localStorage.removeItem(getStorageKey('field-notes', tour.id));
    localStorage.removeItem(getStorageKey('current-stop-index', tour.id));
    clearLocalEvents();
    setVisitedStops([]);
    setActivatedOffers([]);
    setSavedStops([]);
    setLoyaltyStamps({});
    setRecentEvents([]);
    setFieldNotes({});
    setCurrentStopIndex(0);
  };

  const exportDemoEvents = () => {
    const eventExport = {
      exportedAt: new Date().toISOString(),
      tourId: tour.id,
      tourTitle: tour.title,
      visitedStops,
      savedStops,
      activatedOffers,
      loyaltyStamps,
      fieldNotes,
      currentFieldNote,
      events: getTourEvents()
    };
    const blob = new Blob([JSON.stringify(eventExport, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `tour-engine-${tour.id}-demo-events.json`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  };

  const tabText = useMemo(() => {
    if (!currentStop) return '';
    if (activeTab === 'On approach') return currentStop.onApproach;
    if (activeTab === 'At the stop') return currentStop.atStop;
    if (activeTab === 'Safety') return currentStop.safety;
    return currentStop.offerHint;
  }, [activeTab, currentStop]);

  const isCameraRoute = tour.id === 'osaka-camera-crawl';
  const fieldTestPrompts = isCameraRoute
    ? [
      'Does this shop belong in the route, or is it just a listing?',
      'Would a condition/compatibility/tax-free checklist help here?',
      'Tap Useful / Spammy / Confusing for the retail prompt.',
      'Add one quick note about price, stock, floor layout, language support, or buying friction.'
    ]
    : [
      'Does the stop make sense when you are physically here?',
      'Tap Useful / Spammy / Confusing for the offer moment.',
      'Add one quick note if the map cue, story, safety note, or business prompt feels off.',
      'Use Mark Visited to advance and preserve the event trail.'
    ];
  const fieldNotePlaceholder = isCameraRoute
    ? 'Quick camera-shop notes: worth the stop, price looked good/bad, used condition concerns, tax-free friction, floor hard to find, English support, stock surprise, etc.'
    : 'Quick notes after this stop: hard to find, offer felt natural, too much text, etc.';

  if (!currentStop) {
    return <div className="p-6">Tour pack needs stops before it can be played.</div>;
  }

  return (
    <div className="h-screen bg-slate-100 flex flex-col overflow-hidden relative">
      <div className="absolute top-0 left-0 right-0 z-20 bg-white/92 backdrop-blur-md shadow-sm px-4 py-3 flex flex-col pb-4">
        <div className="flex items-center justify-between mb-2">
          <button onClick={() => navigate(-1)} className="p-2 -ml-2 rounded-full bg-slate-100 text-slate-700">
            <SafeIcon name="X" className="w-5 h-5" />
          </button>
          <div className="text-center">
            <span className="block text-xs font-bold uppercase tracking-widest text-slate-500">{displayTitle}</span>
            <span className="block text-[10px] text-slate-400">PWA Tour Player · no app install required</span>
          </div>
          <div className="relative">
            <button
              onClick={shareFieldTestLink}
              aria-label={reviewerMode ? 'Share field test link' : 'Share tour link'}
              className="p-2 -mr-2 rounded-full bg-emerald-50 text-emerald-700"
            >
              <SafeIcon name="Share2" className="w-5 h-5" />
            </button>
            {shareStatus && (
              <span className="absolute right-0 top-10 whitespace-nowrap rounded-full bg-slate-900 px-2 py-1 text-[10px] font-bold text-white shadow">
                {shareStatus}
              </span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-3">
          <span className="text-sm font-bold text-slate-900 whitespace-nowrap">
            Stop {currentStopIndex + 1} <span className="text-slate-400 font-medium">of {tour.stops.length}</span>
          </span>
          <div className="flex-1 h-1.5 bg-slate-200 rounded-full overflow-hidden">
            <div
              className="h-full bg-orange-600 rounded-full transition-all duration-500"
              style={{ width: `${((currentStopIndex + 1) / tour.stops.length) * 100}%` }}
            />
          </div>
        </div>
      </div>

      <StylizedMap currentStop={currentStop} currentStopIndex={currentStopIndex} tour={tour} reviewerMode={reviewerMode} displayTitle={displayTitle} />

      <motion.div
        initial={{ y: '10%' }}
        animate={{ y: 0 }}
        className="bg-[#FDFBF7] rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] relative z-20 -mt-6 max-h-[66vh] flex flex-col"
      >
        <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto mt-4 mb-2 flex-shrink-0" />

        <div className="overflow-y-auto px-5 pb-6">
          <div className="flex items-start justify-between mb-2">
            <div>
              <span className="inline-block bg-purple-100 text-purple-800 text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded mb-2">
                {currentStop.production}
              </span>
              <h2 className="text-2xl font-bold text-slate-900 leading-tight" style={{ fontFamily: 'Georgia, serif' }}>
                {currentStop.title}
              </h2>
              <p className="text-sm text-slate-500 mt-1">{currentStop.location}</p>
            </div>
          </div>

          {currentStop.warning && (
            <div className="mt-3 bg-amber-50 border border-amber-200 rounded-xl p-3 flex gap-3">
              <SafeIcon name="AlertTriangle" className="w-5 h-5 text-amber-600 flex-shrink-0" />
              <p className="text-xs text-amber-800 font-medium">
                {reviewerMode ? `${currentStop.warning}. Keep this stop manual-first; no proximity trigger until reviewed.` : currentStop.warning}
              </p>
            </div>
          )}

          <div className="mt-4 grid grid-cols-4 gap-1 rounded-2xl bg-white p-1 border border-slate-200">
            {tabs.map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`rounded-xl px-2 py-2 text-[10px] font-bold transition ${activeTab === tab ? 'bg-slate-900 text-white' : 'text-slate-500'}`}
              >
                {tab}
              </button>
            ))}
          </div>

          <div className="mt-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-2">{activeTab}</p>
            <p className="text-sm leading-relaxed text-slate-700">{tabText}</p>
          </div>

          <div className="mt-4 bg-white border border-slate-200 rounded-2xl p-4 shadow-sm flex items-center gap-4">
            <button
              onClick={toggleNarration}
              className="w-14 h-14 bg-slate-900 rounded-full flex items-center justify-center text-white flex-shrink-0 shadow-md active:scale-95 transition-transform"
            >
              {isPlaying ? <SafeIcon name="Pause" className="w-6 h-6" /> : <SafeIcon name={narrationStatus === 'audio-ready' ? 'Play' : 'FileText'} className="w-6 h-6 ml-1" />}
            </button>
            <div className="flex-1">
              <p className="text-sm font-bold text-slate-900">Play narration</p>
              <p className="text-xs text-slate-500">{currentStop.audioDuration} · {narrationLabel}</p>
              <p className="mt-1 text-[10px] font-bold uppercase tracking-widest text-slate-400">{narrationLanguageLabel}</p>
              {narrationTrack?.audioUrl && (
                <div className="mt-3 space-y-2">
                  <audio
                    ref={audioRef}
                    src={`${import.meta.env.BASE_URL}${narrationTrack.audioUrl.replace(/^\//, '')}`}
                    onPlay={() => { setIsPlaying(true); setAudioStatus('Playing audio'); }}
                    onPause={() => { setIsPlaying(false); setAudioStatus('Paused'); }}
                    onEnded={() => { setIsPlaying(false); setAudioStatus('Finished'); }}
                    preload="metadata"
                    controls
                    className="w-full"
                  />
                  <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{audioStatus || 'Native audio controls available'}</p>
                  {reviewerMode && narrationLanguage !== 'english' && (
                    <div className="rounded-xl bg-slate-50 p-3">
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Generated audio script</p>
                      <p className="mt-1 text-xs leading-relaxed text-slate-600">{generatedAudioScript || 'Audio language may differ from the visible English field-test script.'}</p>
                    </div>
                  )}
                </div>
              )}
              <div className="mt-2 h-2 rounded-full bg-slate-100 overflow-hidden">
                <div className={`h-full rounded-full ${isPlaying ? 'w-2/3 bg-orange-600' : 'w-1/4 bg-slate-300'} transition-all`} />
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3 mt-4">
            <button
              onClick={openCurrentStopInMaps}
              className="bg-white border border-slate-200 text-slate-700 py-3 rounded-xl font-semibold shadow-sm text-sm flex justify-center items-center gap-2 active:scale-95"
            >
              <SafeIcon name="MapPin" className="w-4 h-4" />
              {exactMapsAllowed ? 'Open in Maps' : 'Open Area'}
            </button>
            <button
              onClick={saveCurrentStop}
              className={`bg-white border py-3 rounded-xl font-semibold shadow-sm text-sm flex justify-center items-center gap-2 active:scale-95 ${savedStops.includes(currentStop.id) ? 'border-emerald-100 text-emerald-700 bg-emerald-50' : 'border-slate-200 text-slate-700'}`}
            >
              <SafeIcon name={savedStops.includes(currentStop.id) ? 'Check' : 'Bookmark'} className="w-4 h-4" />
              {savedStops.includes(currentStop.id) ? 'Saved' : 'Save Stop'}
            </button>
          </div>

          <div className="mt-5 border-t border-slate-200/60 pt-4">
            <p className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-3">Local business layer</p>
            {business && offer && loyaltyProgram ? (
              <div className="space-y-3">
                <div className="bg-white border border-orange-100 rounded-2xl p-4 shadow-sm">
                  <div className="flex items-start gap-3">
                    <div className="w-12 h-12 rounded-2xl bg-orange-100 flex items-center justify-center text-orange-700 flex-shrink-0">
                      <SafeIcon name="Gift" className="w-6 h-6" />
                    </div>
                    <div className="flex-1">
                      <p className="text-[10px] font-bold uppercase tracking-widest text-orange-700">{offerRelevanceLabel}</p>
                      <h3 className="text-sm font-bold text-slate-900">{business.name}</h3>
                      <p className="text-xs text-slate-500">{business.distanceLabel} · {business.category}</p>
                      <p className="mt-2 text-lg font-black text-slate-900 leading-tight">{offerTitle}</p>
                      <p className="mt-1 text-xs text-slate-600 leading-relaxed">{offerDescription}</p>
                      <button
                        onClick={activateOffer}
                        className={`mt-3 w-full rounded-xl py-3 text-xs font-bold uppercase tracking-widest transition ${offerActive ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-slate-900 text-white active:scale-95'}`}
                      >
                        {offerActive ? reviewerMode ? 'Offer active · DEMO-CODE' : 'Saved for this stop' : reviewerMode ? 'Activate offer' : 'Save idea'}
                      </button>
                    </div>
                  </div>
                </div>

                <div className="bg-white border border-slate-100 rounded-2xl p-4 shadow-sm">
                  <div className="flex items-center justify-between mb-3">
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{reviewerMode ? 'Demo loyalty' : 'Visit progress'}</p>
                      <h3 className="text-sm font-bold text-slate-900">{loyaltyProgram.name}</h3>
                    </div>
                    {reviewerMode && <span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold text-slate-600 uppercase">{loyaltyProgram.verificationMode}</span>}
                  </div>
                  <div className="flex gap-2 mb-3">
                    {[...Array(loyaltyProgram.requiredStamps)].map((_, index) => (
                      <div key={index} className={`flex-1 aspect-square rounded-xl border-2 flex items-center justify-center ${index < stampCount ? 'bg-orange-600 border-orange-600 text-white' : 'bg-slate-50 border-slate-200 text-slate-200'}`}>
                        <SafeIcon name={index < stampCount ? 'Check' : 'Circle'} className="w-4 h-4" />
                      </div>
                    ))}
                  </div>
                  <p className="text-xs text-slate-600">{stampCount} of {loyaltyProgram.requiredStamps} {reviewerMode ? 'demo visits logged' : 'visits saved'} · reward: {loyaltyProgram.reward}</p>
                  <button
                    onClick={addLoyaltyStamp}
                    disabled={stampCount >= loyaltyProgram.requiredStamps}
                    className={`mt-3 w-full rounded-xl py-3 text-xs font-bold uppercase tracking-widest transition ${stampCount >= loyaltyProgram.requiredStamps ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-orange-600 text-white active:scale-95'}`}
                  >
                    {stampCount >= loyaltyProgram.requiredStamps ? 'Reward unlocked' : reviewerMode ? 'Add demo stamp' : 'Save visit'}
                  </button>
                </div>
              </div>
            ) : (
              <div>
                {reviewerMode && firstOfferStop && currentStop.id !== firstOfferStop.id && (
                  <button
                    onClick={jumpToOfferStop}
                    className="mb-3 w-full rounded-2xl border border-orange-100 bg-orange-50 p-3 text-left text-xs font-semibold text-orange-900 active:scale-[0.99]"
                  >
                    <span className="block text-[10px] font-bold uppercase tracking-widest text-orange-700">Fast demo shortcut</span>
                    Jump to route position {firstOfferStopIndex + 1}: {firstOfferStop.title}, where the contextual merchant offer appears.
                  </button>
                )}
                <div className="flex gap-3 overflow-x-auto hide-scrollbar pb-2">
                  {['Coffee', 'Lunch', 'Parking', 'Tickets'].map((item) => (
                  <div key={item} className="min-w-[118px] bg-white border border-slate-100 rounded-xl p-3 shadow-sm">
                    <div className="w-8 h-8 rounded-full bg-orange-100 flex items-center justify-center text-orange-600 mb-2">
                      <SafeIcon name={item === 'Parking' ? 'Navigation' : item === 'Tickets' ? 'Tag' : 'Coffee'} className="w-4 h-4" />
                    </div>
                    <p className="text-xs font-bold text-slate-900">{item}</p>
                    <p className="text-[10px] text-slate-500">{reviewerMode ? 'contextual offer slot' : 'nearby idea'}</p>
                  </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {reviewerMode && <div className="mt-5 rounded-2xl border border-blue-100 bg-blue-50 p-4">
            <div className="mb-3 flex items-start gap-3">
              <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-2xl bg-blue-100 text-blue-700">
                <SafeIcon name="ClipboardCheck" className="h-5 w-5" />
              </div>
              <div>
                <p className="text-[10px] font-bold uppercase tracking-widest text-blue-700">Phone field test</p>
                <h3 className="text-sm font-bold text-slate-900">What to check at each stop</h3>
              </div>
            </div>
            <ol className="space-y-2 pl-4 text-xs leading-relaxed text-slate-700">
              {fieldTestPrompts.map(prompt => (
                <li key={prompt} className="list-decimal">{prompt}</li>
              ))}
            </ol>
          </div>}

          {reviewerMode && <div className="mt-5 border-t border-slate-200/60 pt-4">
            <div className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm">
              <div className="mb-3 flex items-start justify-between gap-3">
                <div>
                  <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Field test notes</p>
                  <h3 className="text-sm font-bold text-slate-900">Quick reaction capture</h3>
                </div>
                <span className="rounded-full bg-amber-50 px-2 py-1 text-[10px] font-bold uppercase text-amber-700">local</span>
              </div>
              <div className="mb-3 grid grid-cols-3 gap-2">
                {[
                  ['useful', 'Useful'],
                  ['spammy', 'Spammy'],
                  ['confusing', 'Confusing']
                ].map(([signal, label]) => (
                  <button
                    key={signal}
                    onClick={() => addFieldSignal(signal)}
                    className="rounded-xl border border-slate-200 bg-slate-50 py-2 text-[10px] font-bold uppercase tracking-widest text-slate-700 active:scale-95"
                  >
                    {label}
                  </button>
                ))}
              </div>
              <p className="mb-2 text-[10px] font-bold uppercase tracking-widest text-slate-400">Stop-specific note · {currentStop.title}</p>
              <textarea
                value={currentFieldNote}
                onChange={(event) => saveFieldNote(event.target.value)}
                placeholder={fieldNotePlaceholder}
                className="min-h-20 w-full rounded-xl border border-slate-200 bg-slate-50 p-3 text-xs text-slate-700 outline-none focus:border-orange-300"
              />
            </div>
          </div>}

          {reviewerMode && recentEvents.length > 0 && (
            <div className="mt-5 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
              <div className="mb-3 flex items-center justify-between gap-3">
                <div>
                  <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Local event log</p>
                  <h3 className="text-sm font-bold text-slate-900">Demo activity trail</h3>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => navigate(withPreviewMode(`/evidence/${tour.id}`, location.search))}
                    className="rounded-full bg-orange-50 px-2 py-1 text-[10px] font-bold uppercase text-orange-700 transition hover:bg-orange-100"
                  >
                    Evidence
                  </button>
                  <button
                    onClick={exportDemoEvents}
                    className="rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-bold uppercase text-emerald-700 transition hover:bg-emerald-100"
                  >
                    Export
                  </button>
                  <button
                    onClick={resetDemoState}
                    className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold uppercase text-slate-500 transition hover:bg-slate-200"
                  >
                    Reset
                  </button>
                </div>
              </div>
              <div className="space-y-2">
                {recentEvents.map(event => (
                  <div key={event.id} className="rounded-xl bg-slate-50 px-3 py-2">
                    <div className="flex items-center justify-between gap-3">
                      <span className="text-xs font-bold text-slate-800">{event.type.replaceAll('_', ' ')}</span>
                      <span className="text-[10px] text-slate-400">{new Date(event.createdAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}</span>
                    </div>
                    <p className="mt-1 truncate text-[10px] text-slate-500">{event.payload?.businessId || event.payload?.stopId || event.payload?.tourId}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="mt-5 grid grid-cols-[1fr_1fr] gap-3">
            <button
              onClick={() => setShowStopDetail(true)}
              className="bg-slate-100 text-slate-800 py-4 rounded-xl font-bold text-sm flex items-center justify-center gap-2"
            >
              <SafeIcon name="BookOpen" className="w-4 h-4" />
              Full Notes
            </button>
            <button
              onClick={markVisited}
              className="bg-slate-900 text-white py-4 rounded-xl font-bold text-sm shadow-md flex items-center justify-center gap-2"
            >
              Mark Visited
              <SafeIcon name="ArrowRight" className="w-4 h-4" />
            </button>
          </div>
        </div>
      </motion.div>

      <AnimatePresence>
        {showStopDetail && (
          <motion.div
            initial={{ y: '100%' }}
            animate={{ y: 0 }}
            exit={{ y: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="absolute inset-0 bg-[#FDFBF7] z-50 overflow-y-auto"
          >
            <div className="h-56 bg-gradient-to-br from-slate-900 via-slate-700 to-orange-900 relative">
              <button
                onClick={() => setShowStopDetail(false)}
                className="absolute top-4 right-4 w-10 h-10 bg-black/50 backdrop-blur rounded-full flex items-center justify-center text-white"
              >
                <SafeIcon name="X" className="w-5 h-5" />
              </button>
              <div className="absolute bottom-5 left-6 right-6 text-white">
                <p className="text-xs font-bold uppercase tracking-widest text-orange-200">Stop {currentStop.number}</p>
                <h2 className="text-3xl font-bold" style={{ fontFamily: 'Georgia, serif' }}>{currentStop.title}</h2>
              </div>
            </div>

            <div className="p-6 space-y-6">
              <section>
                <h3 className="text-sm font-bold uppercase tracking-widest text-slate-900 mb-2 border-b border-slate-200 pb-2">Why it matters</h3>
                <p className="text-slate-600 text-sm leading-relaxed">{currentStop.whyItMatters}</p>
              </section>
              <section>
                <h3 className="text-sm font-bold uppercase tracking-widest text-slate-900 mb-2 border-b border-slate-200 pb-2">Narration script</h3>
                <p className="text-slate-600 text-sm leading-relaxed">{currentStop.atStop}</p>
              </section>
              <section className="bg-amber-50 p-4 rounded-xl border border-amber-200">
                <h3 className="text-sm font-bold flex items-center gap-2 text-amber-900 mb-2">
                  <SafeIcon name="Shield" className="w-4 h-4" />
                  Publishing guardrail
                </h3>
                <p className="text-xs text-amber-800">Coordinates and rights should be field-verified before this pack is sold or proximity-triggered.</p>
              </section>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
