export function getNarrationTrack(tourId, stopId, language = narrationManifest.defaults.language) {
  return narrationManifest.tracks[`${tourId}:${stopId}:${language}`]
    || narrationManifest.tracks[`${tourId}:${stopId}`]
    || null;
}

export function getNarrationStatus(tourId, stopId, language) {
  const track = getNarrationTrack(tourId, stopId, language);
  if (track?.audioUrl) return 'audio-ready';
  if (track?.scriptReady) return 'script-ready';
  return 'script-only';
}

export function getNarrationVoice(language = narrationManifest.defaults.language) {
  return narrationVoices[language] || narrationVoices.english;
}
